"""TamperGenerator – generates dynamic SQLmap tamper scripts.

Writes syntactically validated Python tamper scripts to the SQLmap tamper
directory (or a local fallback path) based on logic provided by the
``ScriptWriterAgent``.
"""

from __future__ import annotations

import ast
import logging
from pathlib import Path

logger = logging.getLogger(__name__)

_TAMPER_TEMPLATE = '''\
#!/usr/bin/env python
# Custom tamper script generated by ScriptWriterAgent (Purple Engine)
# Description: {description}

from lib.core.enums import PRIORITY

__priority__ = PRIORITY.NORMAL


def dependencies() -> None:
    pass


def tamper(payload: str, **kwargs) -> str:
    """{description}"""
    if payload:
        {logic}
    return payload
'''


class TamperGenerator:
    """Generates dynamic SQLmap tamper scripts.

    Parameters
    ----------
    tamper_dir:
        Primary directory to write tamper scripts into.
        Defaults to ``/usr/share/sqlmap/tamper/``.
    fallback_dir:
        Directory used when the primary location is not writable.
        Defaults to the current working directory.
    """

    def __init__(
        self,
        tamper_dir: str = "/usr/share/sqlmap/tamper/",
        fallback_dir: str | None = None,
    ) -> None:
        self.tamper_dir = Path(tamper_dir)
        self.fallback_dir = Path(fallback_dir) if fallback_dir else Path.cwd()

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def write_tamper(
        self,
        name: str,
        logic: str,
        description: str = "Custom WAF bypass tamper",
    ) -> str:
        """Write a new tamper script and return the path to the created file.

        Parameters
        ----------
        name:
            Base filename (without ``.py``) for the tamper script.
        logic:
            A single Python expression/statement applied to the ``payload``
            variable.  Must be syntactically valid Python.
        description:
            Human-readable description embedded in the script docstring.

        Returns
        -------
        str
            Absolute path to the written file.

        Raises
        ------
        ValueError
            If *logic* is not valid Python syntax.
        """
        self._validate_logic(logic)

        safe_name = self._sanitise_name(name)
        content = _TAMPER_TEMPLATE.format(
            description=description,
            logic=logic,
        )
        return str(self._write_file(safe_name, content))

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------

    @staticmethod
    def _validate_logic(logic: str) -> None:
        """Raise ``ValueError`` if *logic* is not syntactically valid Python."""
        try:
            ast.parse(logic)
        except SyntaxError as exc:
            raise ValueError(
                f"tamper_logic is not valid Python: {exc}"
            ) from exc

    @staticmethod
    def _sanitise_name(name: str) -> str:
        """Return a filesystem-safe version of *name*."""
        return "".join(c if c.isalnum() or c == "_" else "_" for c in name)

    def _write_file(self, name: str, content: str) -> Path:
        """Try the primary directory first, fall back if not writable."""
        for target_dir in (self.tamper_dir, self.fallback_dir):
            try:
                target_dir.mkdir(parents=True, exist_ok=True)
                file_path = target_dir / f"{name}.py"
                file_path.write_text(content, encoding="utf-8")
                logger.info("Tamper script written to %s", file_path)
                return file_path
            except (PermissionError, OSError) as exc:
                logger.warning(
                    "Cannot write to %s (%s); trying fallback.", target_dir, exc
                )

        raise OSError(
            f"Unable to write tamper script '{name}' to any target directory."
        )
